function validate([forts]) {
  if (!Array.isArray(forts) || forts.length < 1 || forts.length > 1000) return 'forts needs 1 to 1000 positions.';
  if (forts.some(v => v !== -1 && v !== 0 && v !== 1)) return 'Each position is -1, 0 or 1.';
  return null;
}

