function captureForts(forts) {
  let best = 0;
  let left = -1;
  for (let right = 0; right < forts.length; right++) {
    if (forts[right] === 0) {
      continue;
    }
    if (left !== -1 && forts[left] === -forts[right]) {
      best = Math.max(best, right - left - 1);
    }
    left = right;
  }
  return best;
}

