function captureForts(forts) {
  let result = 0;
  for (let i = 0; i < forts.length; i++) {
    if (forts[i] !== 1) continue;
    for (let j = 0; j < forts.length; j++) {
      if (forts[j] !== -1) continue;
      const lo = Math.min(i, j), hi = Math.max(i, j);
      let ok = true;
      for (let k = lo + 1; k < hi; k++) if (forts[k] !== 0) ok = false;
      if (ok) result = Math.max(result, hi - lo - 1);
    }
  }
  return result;
}

