function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  const zeroShare = size === 'large' ? 0.6 + rand() * 0.39 : rand();
  return [Array.from({ length: n }, () => {
    if (rand() < zeroShare) return 0;
    return rand() < 0.5 ? 1 : -1;
  })];
}
